/* STAGING LOCALE BUILD (pl) — generated by scripts/build_locale_staging.py from /site.js. Same endpoints, captcha flow and Consent Mode logic; only visible strings differ. */
/* The Fundraising Game: early-access signup (Bluefox) */
(function () {
  var LIST_URL = 'https://api.bluefox.email/v1/subscriber-lists/6960f7e0cfa080251b241006';
  var CAPTCHA_URL = 'https://api.bluefox.email/v1/captcha';

  function el(tag, attrs, html) {
    var e = document.createElement(tag);
    for (var k in attrs) e.setAttribute(k, attrs[k]);
    if (html) e.innerHTML = html;
    return e;
  }

  function setup(form, idx) {
    var dark = form.getAttribute('data-theme') === 'dark';
    var probe = null;
    var btn = form.querySelector('button[type="submit"]');
    var btnHtml = btn ? btn.innerHTML : '';

    var wrap = el('div', { class: 'tfg-captcha', style: 'display:flex;flex-direction:column;gap:8px;flex-basis:100%' });
    var row = el('div', { style: 'display:flex;align-items:center;gap:10px;flex-wrap:wrap' });
    var img = el('div', { class: 'tfg-captcha-img', 'aria-hidden': 'true', style: 'min-height:50px;min-width:150px;background:#fff;border-radius:10px;display:flex;align-items:center;justify-content:center;overflow:hidden;border:1px solid rgba(18,20,28,0.15)' }, '<span style="font-size:13px;color:#5C564F">Wczytywanie…</span>');
    var refresh = el('button', { type: 'button', 'aria-label': 'Wczytaj nowy kod', style: 'min-height:44px;padding:0 14px;border-radius:999px;border:1px solid rgba(18,20,28,0.25);background:transparent;color:#12141C;font:inherit;font-size:14px;cursor:pointer' }, 'Nowy kod');
    row.appendChild(img); row.appendChild(refresh);
    var id = 'tfg-captcha-' + idx;
    var label = el('label', { for: id, style: 'font-size:14px;font-weight:600;color:#12141C' }, 'Proszę przepisać znaki z obrazka');
    var input = el('input', { id: id, name: 'captchaText', type: 'text', required: '', autocomplete: 'off', placeholder: 'Kod', style: 'min-height:54px;padding:0 18px;border-radius:14px;border:1px solid rgba(18,20,28,0.25);background:#FFFFFF;color:#12141C;font:inherit;font-size:16px' });
    wrap.appendChild(label); wrap.appendChild(row); wrap.appendChild(input);
    var msg = el('p', { role: 'alert', style: 'display:none;margin:0;font-size:14px;color:#B23A1E;flex-basis:100%' });

    if (btn) { btn.parentNode.insertBefore(wrap, btn); btn.parentNode.insertBefore(msg, btn); }
    else form.appendChild(wrap);

    function load() {
      img.innerHTML = '<span style="font-size:13px;color:#5C564F">Wczytywanie…</span>';
      fetch(CAPTCHA_URL).then(function (r) { return r.json(); }).then(function (d) {
        img.innerHTML = d.result.data; probe = d.result.probe; input.value = '';
      }).catch(function () { img.innerHTML = '<span style="font-size:13px;color:#B23A1E">Nie udało się wczytać kodu</span>'; });
    }
    refresh.addEventListener('click', load);
    load();

    form.addEventListener('submit', function (e) {
      e.preventDefault();
      msg.style.display = 'none';
      var email = form.querySelector('input[name="email"]').value.trim();
      if (btn) { btn.disabled = true; btn.innerHTML = 'Wysyłanie…'; }
      fetch(LIST_URL, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: email, captchaText: input.value.trim(), captchaProbe: probe })
      }).then(function (r) {
        if (r.ok) {
          var box = el('div', { role: 'status', style: 'display:flex;flex-direction:column;gap:10px' },
            '<h3 style="margin:0;font-family:\'Instrument Serif\',Georgia,serif;font-weight:400;font-size:34px;line-height:1.1;color:#12141C">Zapis przyjęty.</h3>' +
            '<p style="margin:0;color:#4A453F">Prosimy potwierdzić zapis w skrzynce e-mail. Rozdział bonusowy (po angielsku) jest już w drodze.</p>');
          form.parentNode.replaceChild(box, form);
          return;
        }
        return r.json().catch(function () { return {}; }).then(function (d) {
          throw new Error((d && d.error && d.error.message) || 'Coś poszło nie tak. Prosimy spróbować ponownie.');
        });
      }).catch(function (err) {
        msg.textContent = err.message === 'Failed to fetch' ? 'Błąd sieci. Prosimy sprawdzić połączenie i spróbować ponownie.' : err.message;
        msg.style.display = 'block';
        if (btn) { btn.disabled = false; btn.innerHTML = btnHtml; }
        load();
      });
    });
  }

  function init() {
    var forms = document.querySelectorAll('form[data-signup]');
    for (var i = 0; i < forms.length; i++) setup(forms[i], i);
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
})();

/* Google Analytics 4 (G-HKGBHJZMNC) with cookie consent (Consent Mode v2, basic) */
(function () {
  var GA_ID = 'G-HKGBHJZMNC';
  var KEY = 'tfg_cookie_consent';
  var loaded = false;

  window.dataLayer = window.dataLayer || [];
  window.gtag = window.gtag || function () { window.dataLayer.push(arguments); };
  gtag('consent', 'default', {
    ad_storage: 'denied', ad_user_data: 'denied', ad_personalization: 'denied',
    analytics_storage: 'denied', wait_for_update: 500
  });

  function getChoice() { try { return localStorage.getItem(KEY); } catch (e) { return null; } }
  function setChoice(v) { try { localStorage.setItem(KEY, v); } catch (e) {} }

  function loadGA() {
    if (loaded) return; loaded = true;
    gtag('consent', 'update', { analytics_storage: 'granted' });
    var s = document.createElement('script');
    s.async = true; s.src = 'https://www.googletagmanager.com/gtag/js?id=' + GA_ID;
    document.head.appendChild(s);
    gtag('js', new Date());
    gtag('config', GA_ID);
  }

  function removeGACookies() {
    document.cookie.split(';').forEach(function (c) {
      var n = c.split('=')[0].trim();
      if (n === '_ga' || n.indexOf('_ga_') === 0) {
        var host = location.hostname.replace(/^www\./, '');
        ['', '; domain=' + host, '; domain=.' + host].forEach(function (d) {
          document.cookie = n + '=; expires=Thu, 01 Jan 1970 00:00:00 GMT; path=/' + d;
        });
      }
    });
  }

  function clearBannerPad() {
    document.body.style.paddingBottom = '';
  }

  function banner() {
    if (document.getElementById('tfg-cookie')) return;
    var b = document.createElement('div');
    b.id = 'tfg-cookie';
    b.setAttribute('role', 'dialog');
    b.setAttribute('aria-label', 'Zgoda na pliki cookie');
    /* In-flow sticky consent region: reserves layout space so it cannot cover hub cards/CTAs. Consent Mode defaults/controls unchanged. */
    b.style.cssText = 'position:sticky;bottom:0;left:0;right:0;z-index:9999;width:100%;max-width:none;margin:0;box-sizing:border-box;background:#12141C;color:#F5F1EA;border-top:1px solid rgba(245,241,234,.18);padding:16px 24px;box-shadow:0 -8px 24px rgba(0,0,0,.2);font-size:15px;line-height:1.5;display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px 20px';
    b.innerHTML = '<p style="margin:0;flex:1 1 280px;max-width:720px">Używamy plików cookie Google Analytics, aby zrozumieć, jak odwiedzający korzystają z witryny. Bez Państwa zgody nic nie jest śledzone.</p>' +
      '<div style="display:flex;gap:10px;flex-wrap:wrap;justify-content:flex-end;flex:0 0 auto">' +
      '<button type="button" data-c="denied" style="min-height:44px;padding:0 18px;border-radius:999px;border:1px solid rgba(245,241,234,.4);background:transparent;color:#F5F1EA;font:inherit;cursor:pointer">Odrzucam</button>' +
      '<button type="button" data-c="granted" style="min-height:44px;padding:0 18px;border-radius:999px;border:0;background:#F5F1EA;color:#12141C;font:inherit;font-weight:600;cursor:pointer">Akceptuję</button></div>';
    b.addEventListener('click', function (e) {
      var v = e.target && e.target.getAttribute('data-c');
      if (!v) return;
      setChoice(v);
      if (v === 'granted') loadGA();
      else { gtag('consent', 'update', { analytics_storage: 'denied' }); removeGACookies(); }
      b.parentNode.removeChild(b);
    });
    var footer = document.querySelector('footer');
    if (footer && footer.parentNode) footer.parentNode.insertBefore(b, footer);
    else document.body.appendChild(b);
  }

  function addSettingsLink() {
    var f = document.querySelector('footer');
    if (!f || document.getElementById('tfg-cookie-settings')) return;
    var a = document.createElement('a');
    a.id = 'tfg-cookie-settings'; a.href = '#'; a.textContent = 'Ustawienia plików cookie';
    a.style.cssText = 'display:inline-block;margin-top:12px;font-size:13px;opacity:.75;color:inherit';
    a.addEventListener('click', function (e) { e.preventDefault(); banner(); });
    f.appendChild(a);
  }

  window.tfgCookieSettings = banner;
  var choice = getChoice();
  if (choice === 'granted') loadGA();

  function init() { if (!choice) banner(); addSettingsLink(); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
})();
